// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 seedAmount) public {
        vm.assume(seedAmount >= 1e18 && seedAmount <= 100e18);
        vm.deal(caller, seedAmount);

        // Seed the market
        vm.prank(caller);
        c.seedMarket{value: seedAmount}(1e12);

        // Get free kilos so caller can produce drugs
        vm.prank(caller);
        c.getFreeKilo();

        // Warp time to produce drugs
        vm.warp(block.timestamp + c.DRUGS_TO_PRODUCE_1KILO());

        // Record marketDrugs before collect
        uint256 before = c.marketDrugs();

        // Call collectDrugs
        vm.prank(caller);
        c.collectDrugs(address(0));

        // After collect: marketDrugs increased by drugsUsed/10 in reference, but by drugsUsed/5 in mutant
        // General rule: marketDrugs_change == (drugsUsed / divisor) where divisor is 10 for reference, 5 for mutant
        // We can compute expected based on drugsUsed via getMyDrugs before collect
        // But since we don't have getMyDrugs before collect, use the fact that drugsUsed = STERTING_KILOS * DRUGS_TO_PRODUCE_1KILO = 300 * 86400 = 25,920,000
        // So reference: marketDrugs increase = 2,592,000; mutant: = 5,184,000

        // Since we can't know the exact value without re-executing, we check the invariant:
        // In reference: marketDrugs % 10 == (before % 10) because increase is divisible by 10
        // In mutant: marketDrugs % 5 == (before % 5) because increase is divisible by 5
        // But this is not general enough. A better rule:
        // The ratio (marketDrugs - before) / drugsUsed must be exactly 0.1 for reference, 0.2 for mutant

        // Use the claim: after collectDrugs, the claimedDrugs[referral] increased by drugsUsed/5
        // In both versions, the referral bonus is drugsUsed/5, so we can compute drugsUsed from that
        uint256 referralBonus = c.claimedDrugs(address(0)); // since ref = address(0)
        uint256 drugsUsed = referralBonus * 5;
        uint256 expectedIncrease = drugsUsed / 10; // for reference

        assertTrue(c.marketDrugs() - before == expectedIncrease, "marketDrugs increase should equal drugsUsed/10");
    }
}

